    private static void add(String key,String...values){if(values.length!=6||COPY.put(key,values)!=null)throw new IllegalStateException(key);}
    static String get(String language,String key,Object...args){String[]values=COPY.get(key);if(values==null)throw new IllegalArgumentException(key);String normalized=Strings.normalize(language);int index=Arrays.asList("en","fr","de","es","pt","it").indexOf(normalized);String value=values[Math.max(0,index)];return args.length==0?value:String.format(Locale.forLanguageTag(normalized),value,args);}
